#include <WiFi.h>
#include <PubSubClient.h>

const char* WIFI_NOM = "MaktabWiFi";
const char* WIFI_PAROL = "parol12345";
const char* BROKER = "broker.hivemq.com";     // bepul ochiq broker

WiFiClient wifi;
